analysis_script = '''import re, json, sys

raw = sys.stdin.read()
cells = {}
for line in raw.strip().split("\\n"):
    m = re.match(r"\\((\\d+),\\s*(\\d+)\\):\\s*(.*)", line.strip())
    if m:
        r, c, v = int(m.group(1)), int(m.group(2)), m.group(3).strip()
        cells[f"{r},{c}"] = v

max_row = max(int(k.split(",")[0]) for k in cells)
max_col = max(int(k.split(",")[1]) for k in cells)

headers = {}
for c in range(1, max_col + 1):
    headers[c] = cells.get(f"1,{c}", f"Col{c}")

rows = []
for r in range(2, max_row + 1):
    row = {}
    for c in range(1, max_col + 1):
        row[headers[c]] = cells.get(f"{r},{c}", "")
    rows.append(row)

# Identify columns
h_lower = {c: h.lower() for c, h in headers.items()}
amount_col = cat_col = date_col = loc_col = desc_col = curr_col = None
for c, h in h_lower.items():
    if not amount_col and any(k in h for k in ["amount","cost","total","price"]):
        amount_col = headers[c]
    if not cat_col and any(k in h for k in ["category","type"]):
        cat_col = headers[c]
    if not date_col and "date" in h:
        date_col = headers[c]
    if not loc_col and any(k in h for k in ["destination","location","city"]):
        loc_col = headers[c]
    if not desc_col and any(k in h for k in ["description","purpose","notes","item"]):
        desc_col = headers[c]
    if not curr_col and "currency" in h:
        curr_col = headers[c]

# Parse amounts
amounts = []
for row in rows:
    v = row.get(amount_col, "")
    if v:
        try:
            amounts.append(float(v))
        except:
            pass

total = sum(amounts)
result = {
    "headers": list(headers.values()),
    "row_count": len(rows),
    "total": total,
    "avg": total / len(amounts) if amounts else 0,
    "min": min(amounts) if amounts else 0,
    "max": max(amounts) if amounts else 0,
    "amount_col": amount_col,
    "cat_col": cat_col,
    "date_col": date_col,
    "loc_col": loc_col,
    "desc_col": desc_col,
}

# Category breakdown
if cat_col:
    cats = {}
    for row in rows:
        cat = row.get(cat_col, "Unknown") or "Unknown"
        v = row.get(amount_col, "")
        if v:
            try:
                a = float(v)
                if cat not in cats:
                    cats[cat] = {"total": 0, "count": 0}
                cats[cat]["total"] += a
                cats[cat]["count"] += 1
            except:
                pass
    result["by_category"] = cats

# Destination breakdown
if loc_col:
    locs = {}
    for row in rows:
        loc = row.get(loc_col, "Unknown") or "Unknown"
        v = row.get(amount_col, "")
        if v:
            try:
                a = float(v)
                if loc not in locs:
                    locs[loc] = {"total": 0, "count": 0}
                locs[loc]["total"] += a
                locs[loc]["count"] += 1
            except:
                pass
    result["by_destination"] = locs

# Date range
if date_col:
    dates = sorted([row[date_col] for row in rows if row.get(date_col, "")])
    if dates:
        result["date_range"] = {"from": dates[0], "to": dates[-1]}

# All line items
items = []
for row in rows:
    item = {}
    if date_col: item["date"] = row.get(date_col, "")
    if desc_col: item["description"] = row.get(desc_col, "")
    if cat_col: item["category"] = row.get(cat_col, "")
    if loc_col: item["destination"] = row.get(loc_col, "")
    if amount_col: item["amount"] = row.get(amount_col, "")
    if curr_col: item["currency"] = row.get(curr_col, "")
    items.append(item)
result["items"] = items

print(json.dumps(result))
'''
